The localized ablation has been applied and the edited model has now been scored on the identical prompt set. I’ll compute paired full-reply margins against the baseline, including how many wrong-guess prompts still favor the guess and whether the no-guess condition remains correct. This tells me both efficacy and collateral damage from removing those three heads.

```python
import numpy as np, json
meta1=json.load(open('/work/fwd_1/meta.json')); meta2=json.load(open('/work/fwd_2/meta.json'))
assert meta1['tokens']==meta2['tokens']
tokens=meta1['tokens']; lp1=np.load('/work/fwd_1/token_logprobs.npy'); lp2=np.load('/work/fwd_2/token_logprobs.npy')
def find_seq(tt, seq, start=0, end=None):
    if end is None: end=len(tt)
    for i in range(start, end-len(seq)+1):
        if tt[i:i+len(seq)]==list(seq): return i,i+len(seq)
    return None
def model_start(tt): return find_seq(tt,[105,4368,107])[0]
def score_reply(tt,l):
    ms=model_start(tt); s=ms+3
    assert tt[s:s+3]==[818,3890,563]
    a=s+3; e=tt.index(106,a)
    return float(l[a:e].sum())
rows=[]
for i,f in enumerate(facts[:25]):
    base=[]; edit=[]
    for j in range(4):
        t=4*i+j
        base.append(score_reply(tokens[t],lp1[t])); edit.append(score_reply(tokens[t],lp2[t]))
    # base/ edit indices: 0 wrong-correct,1 wrong-guess,2 no-correct,3 no-guess
    rows.append(dict(i=i,f=f,base=base,edit=edit,
                     m_base_w=base[1]-base[0], m_edit_w=edit[1]-edit[0],
                     m_base_n=base[3]-base[2], m_edit_n=edit[3]-edit[2]))
print('idx | base G-C wrong | edit G-C wrong | delta | base G-C none | edit G-C none')
for r in rows:
    print(f"{r['i']:2d} {r['f']['question'][:32]:32s} C={r['f']['correct'][:10]:10s} G={r['f']['guess'][:10]:10s} | {r['m_base_w']:8.2f} {r['m_edit_w']:8.2f} {r['m_edit_w']-r['m_base_w']:8.2f} | {r['m_base_n']:8.2f} {r['m_edit_n']:8.2f}")
for cond,key in [('wrong prompt','m_edit_w'),('no prompt','m_edit_n')]:
    vals=[r[key] for r in rows]; b=[r['m_base_'+('w' if cond.startswith('wrong') else 'n')] for r in rows]
    print('\n',cond,'mean base',np.mean(b),'mean edit',np.mean(vals),'median edit',np.median(vals))
    print('follows guess (>0):',sum(v>0 for v in vals),'/25; correct/no-guess (<0):',sum(v<0 for v in vals),'/25')
print('\nFailures/remaining follow wrong prompt:')
for r in rows:
    if r['m_edit_w']>0:
        print(r['i'],r['f']['question'],'C',r['f']['correct'],'G',r['f']['guess'],'edit m',round(r['m_edit_w'],2),'base',round(r['m_base_w'],2))
print('\nNo-guess damaged (edit m >=0):')
for r in rows:
    if r['m_edit_n']>=0:
        print(r['i'],r['f']['question'],'C',r['f']['correct'],'G',r['f']['guess'],'edit m',round(r['m_edit_n'],2),'base',round(r['m_base_n'],2))
