The corrected accounting changes the suspect: layer 17 head 0 is by far the largest single writer toward the guess, contributing about +224 on wrong-guess prompts versus only −9 on no-guess prompts. The layer-18 heads I ablated are smaller and partly cancel each other, which explains the null result. I’ll verify that layer-17 head 0 is actually attending to the guessed answer tokens, then ablate only that head and measure the paired reply margin.

```python
import json, numpy as np
facts=[json.loads(l) for l in open('/practice/dev_facts.jsonl')]
Meta=json.load(open('/work/fwd_3/meta.json')); tokens=Meta['tokens']
def find_seq(tt, seq, start=0, end=None):
    if end is None: end=len(tt)
    for i in range(start, end-len(seq)+1):
        if tt[i:i+len(seq)]==list(seq): return i,i+len(seq)
    return None
def model_start(tt): return find_seq(tt,[105,4368,107])[0]
def user_span(tt):
    a=find_seq(tt,[105,2364,107])[1]; b=tt.index(106,a); return a,b
def sem_start(tt,ms):
    s=ms+3; a=s+3; e=tt.index(106,a); c=tt[a:e]
    if c and c[-1]==236761: c=c[:-1]
    if c and c[0]==236743: return a+1,e,c
    return a,e,c
def loc_guess(tt,g,ms):
    ids=tok.encode(' '+g).ids[1:]
    sp=find_seq(tt,ids,0,ms)
    if sp is None: sp=find_seq(tt,tok.encode(g).ids[1:],0,ms)
    return sp
records=[]
for i,f in enumerate(facts):
    for cond in ['wrong','none']:
        tt=tokens[2*i+(0 if cond=='wrong' else 1)]
        ms=model_start(tt); us,ue=user_span(tt); sem,e,c=sem_start(tt,ms)
        gs=ge=gsem=None
        if cond=='wrong':
            sp=loc_guess(tt,f['guess'],ms)
            if sp:
                gs,ge=sp
                # skip leading space token if present
                if tt[gs]==236743: gsem=gs+1
                else: gsem=gs
        records.append(dict(i=i,cond=cond,tt=tt,ms=ms,us=us,ue=ue,qsem=sem-1,gs=gs,ge=ge,gsem=gsem))
print('mean attention from qsem to guess semantic tokens by layer/head (wrong prompts); and user tokens')
for l in [16,17,18,19,20]:
    A=np.load(f'/work/fwd_3/attn_{l}.npy')
    print('layer',l)
    for h in range(4):
        gs_att=[]; us_att=[]; last_att=[]
        for r in records:
            t=2*r['i']+(0 if r['cond']=='wrong' else 1)
            a=A[t,h,r['qsem'],:]
            if r['cond']=='wrong' and r['gsem'] is not None:
