The current attribution shows three strong remaining copy-related heads before layer 20: layer-18 head 3, layer-18 head 0, and layer-17 head 2, with additional late guess-promoting heads. Before editing further, I’ll measure how much the existing two-head edit has already changed the likelihood of the correct reply in the no-guess condition, to ensure I am not trading away factual knowledge for guess suppression.

```python
import json, numpy as np
facts=[json.loads(l) for l in open('/practice/dev_facts.jsonl')]
def score_replies(path, n=100):
    m=json.load(open(f'{path}/meta.json')); t=m['tokens']; lp=np.load(f'{path}/token_logprobs.npy')
    def find_seq(tt, seq, start=0, end=None):
        if end is None: end=len(tt)
        for i in range(start,end-len(seq)+1):
            if tt[i:i+len(seq)]==list(seq): return i,i+len(seq)
        return None
    def score(tt,l):
        ms=find_seq(tt,[105,4368,107])[0]; s=ms+3
        a=s+3; e=tt.index(106,a)
        return float(l[a:e].sum())
    return [score(t[i],lp[i]) for i in range(n)], t
S3,t3=score_replies('/work/fwd_3')
S7,t7=score_replies('/work/fwd_7')
print('tokens same?',t3==t7)
# fwd3 layout: 2 per fact: wrong-correct index2i, none-correct index2i+1
# fwd7 same layout
print('mean correct reply logprob by condition:')
for cond,ix in [('wrong prompt',lambda i:2*i),('no prompt',lambda i:2*i+1)]:
    a=np.array([S3[ix(i)] for i in range(50)]); b=np.array([S7[ix(i)] for i in range(50)])
    print(cond,'orig',a.mean(),'edited',b.mean(),'delta',(b-a).mean(),'min/max delta',(b-a).min(),(b-a).max())
    print(' improved/unchanged/damaged counts',sum(b>a+0.01),sum(abs(b-a)<=0.01),sum(b<a-0.01))
print('\nper-fact no-prompt correct reply delta:')
for i in range(50):
    d=S7[2*i+1]-S3[2*i+1]
    if abs(d)>0.2:
        print(i,facts[i]['question'][:35],round(d,2))
