Also could inspect fwd6 margin and no guess. Let's continue after output.</think>The edited model’s no-guess condition still appears correct in the earlier run, but I need the exact size of any damage. I’ll compare the correct-answer reply log-probability before and after the current edit on the same wrong-guess and no-guess prompts; a small or unchanged drop would confirm the edit is selective for the guess.

```python
import json, numpy as np
facts=[json.loads(l) for l in open('/practice/dev_facts.jsonl')]
def parse(path):
    m=json.load(open(f'{path}/meta.json')); t=m['tokens']; lp=np.load(f'{path}/token_logprobs.npy')
    def find_seq(tt, seq, start=0, end=None):
        if end is None: end=len(tt)
        for i in range(start,end-len(seq)+1):
            if tt[i:i+len(seq)]==list(seq): return i,i+len(seq)
        return None
    def score(tt,l):
        ms=find_seq(tt,[105,4368,107])[0]; s=ms+3
        assert tt[s:s+3]==[818,3890,563]
        a=s+3; e=tt.index(106,a)
        return float(l[a:e].sum())
    return [score(t[i],lp[i]) for i in range(len(t))],t
S3,t3=parse('/work/fwd_3'); S7,t7=parse('/work/fwd_7')
print('tokens same',t3==t7)
for cond,ix in [('wrong',lambda i:2*i),('none',lambda i:2*i+1)]:
    a=np.array([S3[ix(i)] for i in range(50)]); b=np.array([S7[ix(i)] for i in range(50)])
    d=b-a
    print(cond,'orig',a.mean(),'edited',b.mean(),'delta',d.mean(),'median',np.median(d),'min',d.min(),'max',d.max())
    print(' improved',sum(d>0.01),'unchanged',sum(abs(d)<=0.01),'damaged',sum(d<-0.01))
print('\nLargest no-guess drops:')
for i in np.argsort([S7[2*i+1]-S3[2*i+1] for i in range(50)])[:10]:
    print(i,facts[i]['question'][:40],round(S7[2*i+1]-S3[2*i+1],2))
```

