    for r in rs: print('   ',r['i'],'ans',repr(r['ans']),'val',round(r['val'],3))
    # identify guess by matching gword to answer; for no-guess, use ordering (first listed usually guess if generated pair)
    byans={r['ans']:r for r in rs}
