import numpy as np, json, re
from pathlib import Path

def hf_name(fname):
    nm=fname[:-4] if fname.endswith('.npy') else fname
    m=re.match(r'model_layers_(\d+)_(.+)_weight$', nm)
    if m:
        layer, rest = m.group(1), m.group(2)
        # rest examples: self_attn_o_proj -> self_attn.o_proj
        if rest.startswith('self_attn_'):
            rest = 'self_attn.' + rest[len('self_attn_'):]
        elif rest.startswith('mlp_'):
            rest = 'mlp.' + rest[len('mlp_'):]
        else:
            rest = rest.replace('_', '.')
        return f"model.layers.{layer}.{rest}.weight"
    return nm

def arrs(d):
    out={}
    for f in Path(d).glob('*.npy'):
        out[hf_name(f.name)] = np.load(f)
    return out

def describe_dir(d, only_o=True):
    a=arrs(d)
    print("\n###",Path(d).name)
    for nm,W in sorted(a.items()):
        try:
            W0=load_original(nm).detach().numpy()
        except Exception as e:
            print("  ??",nm,e); continue
        D=W-W0
        fro=float(np.linalg.norm(D))
        if fro < 1e-8:
            print("  ", nm, "UNCHANGED"); continue
        ops=[]
        if W.shape==(1152,1024) and 'o_proj' in nm:
            for h in range(4):
                sl=slice(h*256,(h+1)*256)
                Dh=D[:,sl]; W0h=W0[:,sl]; nd=float(np.linalg.norm(Dh))
                if nd<1e-9: continue
                c=float((Dh*W0h).sum()/max((W0h*W0h).sum(),1e-12))
                resid=Dh-c*W0h
                if np.linalg.norm(resid) < 1e-4*nd:
                    ops.append(f"h{h}:x{c:.3f}")
                else:
                    s=np.linalg.svd(Dh,compute_uv=False)
                    ops.append(f"h{h}:mod(fro={nd:.2f}, top_sv_frac={float(s[0]**2/np.sum(s**2)):.2f})")
        else:
            ops.append(f"mod fro={fro:.3f}")
        print("  ", nm.replace('model.layers.','L').replace('.self_attn.o_proj.weight',''), "; ".join(ops))

for name in ['candC1','candC2','candC3','candC4','candC5','candC6','candC7','candC8','candA2b','edit5','edit6','editA','cand_h3','copycirc','cand_edit5_recovered','cand_b4_L5h23','best_4','best4_recover_163','current_best4_154','edited']:
    p=Path('/work')/name
    if p.exists(): describe_dir(p)

print("\n=== c7/c8 raw dicts ===")
